design:
{
  "v3_sha256": "5409972daeca856ef53c145456caa0659ef644943c6209fce25dc498e9d8b558",
  "requirement_id": "phase:38",
  "proposal_key": "proposal:current-qualification:phase:38",
  "proposed_task": {
    "title": "Qualify phase:38 Idempotency verification gate",
    "type": "task",
    "status": "open",
    "parent": "vb-eirmk",
    "metadata": {
      "master_requirement_ids": [
        "phase:38"
      ],
      "qualification_only": true
    },
    "description": "`SideEffect` + `RetrySafety` classification per action. Verification gate rejects retry on side-effecting actions without idempotency key. Key ingredient validation (reject secrets, random, time in keys). New `IdempotencyViolation` error type. Tests: every side-effect class, key restriction, retry reachability.",
    "acceptance": [
      {
        "kind": "positive_and_negative",
        "clauses": [
          "Positive table-driven cases for each SideEffect/RetrySafety class and permitted retry/key combination; exact retry reachability and typed outcomes.",
          "Negative missing-key case yields IdempotencyViolation before an external effect; reject secret-, random-, and time-derived key ingredients.",
          "Replay/duplicate checks prove recovery never repeats a non-idempotent effect; same-digest duplicate completion is idempotent and different digest yields typed divergence."
        ]
      },
      {
        "kind": "per_clause_family_allocation",
        "clauses": [
          {
            "clause": "Per-action SideEffect/RetrySafety classification",
            "existing_owner_ids": [
              "vb-jpq7.42",
              "vb-5w2c"
            ],
            "bounded_qualification_child_policy": "Only if registered checks do not prove each action class; one bounded evidence child, no implementation placeholder."
          },
          {
            "clause": "Verification gate and IdempotencyViolation",
            "existing_owner_ids": [
              "vb-uoq0",
              "vb-jpq7.42"
            ],
            "bounded_qualification_child_policy": "If gate outcomes are unproven, one bounded check child for allow/reject branches."
          },
          {
            "clause": "Key ingredient restrictions",
            "existing_owner_ids": [
              "vb-jpq7.42",
              "vb-uoq0"
            ],
            "bounded_qualification_child_policy": "If any ingredient class lacks an exact assertion, one scoped evidence child for that class."
          },
          {
            "clause": "Retry reachability and duplicate-effect safety",
            "existing_owner_ids": [
              "vb-jpq7.42",
              "vb-eirmk.10"
            ],
            "bounded_qualification_child_policy": "Use .10 only for its end-to-end replay lane; add an evidence child only for a missing phase38 assertion."
          }
        ]
      }
    ],
    "dependencies": []
  }
}
